const known = value => {
 if(value==null)return 0;
 if(typeof value==='object')return known(value.Value??value.value??value.Val??value.val??value.N??value.n);
 const x=Number(value);return Number.isFinite(x)?x:0;
};
const copySave = input => JSON.parse(JSON.stringify(input));
const rewardLabel = id => SPECIAL_KOREAN_NAMES[id] || '아이템 '+id;
const ruleKey = row => row.n+':'+row.i;
const findRules = (npc,item) => SPECIAL_CONSUMER_RULES.filter(r=>r.n===npc&&r.i===item);

/* This creates a new hypothetical state. It never touches the caller's object.
 * 'unclaimed' resets only the original GetP('get_*') award counters. This is a
 * consumer-only counterfactual; producer RNG, material caps, and seed remain.
 * 'fresh' also clears pre-existing award flags and is a broader, explicitly
 * hypothetical new-account scenario (not validated as native game history).
 */
export function specialScenario(save,mode='current'){
 if(!['current','unclaimed','fresh'].includes(mode))
  throw Error('미지원 특수보상 시나리오');
 const draft=copySave(save);
 draft.globalVariable=draft.globalVariable||{};
 if(mode!=='current'){
  for(const r of SPECIAL_CONSUMER_RULES){
   if(r.k&&r.s!=='temp')draft.globalVariable[r.k]=0;
   if(mode==='fresh')delete draft.globalVariable[r.f];
  }
 }
 return draft;
}
export function originalConsumerRule(npc,item){
 const result=findRules(npc,item);
 return result.length===1?result[0]:null;
}
export function specialRewardName(itemId){
 return rewardLabel(itemId);
}
/* Original SBC contains a conditional recovery branch for the flag value 2.
 * This is exposed as an explicit event, never blindly repeated each clear:
 * triggering recovery on every following visit would fabricate cancellations.
 */
export function restoreOriginalPendingAward(state, npc, item){
 const row=originalConsumerRule(npc,item);
 if(!row)return {applied:false,reason:'원본 지급 함수 미확인'};
 const action=row.rb;
 if(!action||known(state[row.f])!==action.ifFlagEquals)
  return {applied:false,reason:'복구 분기 조건 불충족'};
 state[row.f]=action.resetFlagTo;
 const update=action.counterUpdate;
 if(update){
  if(update.operation==='AddP')state[update.key]=known(state[update.key])+update.value;
  else if(update.operation==='SetP')state[update.key]=update.value;
  else throw Error('알 수 없는 원본 복구 연산');
 }
 return {applied:true,rule:ruleKey(row),counter:update?.key||null};
}
/* Battle-loss branch source contract. The 54506 V174 boss SBC places
 * rollback SetP/AddP under an explicit 'lost' event before general_win.
 * This function is never automatically called after a successful clear.
 * A caller must supply evidence that the battle-loss branch executed.
 * Unknown/unsupported consumer rollbacks are left untouched.
 */
export function applyOriginalBattleLoss(save,npc,{
 includeUnverifiedWhaleRollback=false
}={}){
 const boss=Number(npc);
 const draft=copySave(save);
 draft.globalVariable=draft.globalVariable||{};
 const effects=[],excluded=[];
 for(const rule of SPECIAL_CONSUMER_RULES.filter(r=>r.n===boss)){
  if(!rule.rb)continue;
  // In 54506 the rollback is inside the verified lost event. For the
  // separately recovered Whale consumer only the rollback CONDITION was
  // extracted, not the enclosing event's run-time trigger. Never silently
  // classify it as a 60014 battle-loss action.
  if(rule.originArchive!=='54506-original'&&!includeUnverifiedWhaleRollback){
   if(known(draft.globalVariable[rule.f])===rule.rb.ifFlagEquals)
    excluded.push({npc:boss,itemId:rule.i,
     reason:'Whale 복구 실행 이벤트 확인 전'});
   continue;
  }
  const applied=restoreOriginalPendingAward(draft.globalVariable,boss,rule.i);
  if(applied.applied)effects.push({
   npc:boss,itemId:rule.i,name:rewardLabel(rule.i),
   flag:rule.f,rollback:rule.rb,counter:applied.counter,
   sourceVerifiedLostBranch:rule.originArchive==='54506-original'
  });
 }
 return {nextState:draft,lossEvent:true,npc:boss,effects,excluded,
  changed:effects.length,unverified:excluded.length,
  unsupported:!SPECIAL_CONSUMER_RULES.some(r=>r.n===boss)};
}
function consumerGuard(rule,state,tempState,numericState){
 const numeric=SOURCE_NUMERIC_GUARDS[ruleKey(rule)];
 if(numeric){
  if(numericState==null||
      !Object.prototype.hasOwnProperty.call(numericState,String(numeric.key))||
      numericState[numeric.key]==null)
   return {eligible:null,reason:'숫자형 원본 GetP 조건 상태 미확인'};
  const current=known(numericState[numeric.key]);
  if(!(numeric.operator==='=='&&current===numeric.value))
   return {eligible:false,reason:'숫자형 원본 GetP 지급 조건 불충족'};
 }
 if(rule.review&&!(rule.n===40372&&rule.i===3523))
  return {eligible:null,reason:'원본 추가 지급 제한 독립 검증 필요'};
 const flagValue=known(state[rule.f]);
 if(rule.fc==='== 1'&&flagValue!==1)return {eligible:false,reason:'이번 회차 지급 플래그 없음'};
 if(rule.fc==='~= 0'&&flagValue===0)return {eligible:false,reason:'이번 회차 지급 플래그 없음'};
 if(rule.fc!=='== 1'&&rule.fc!=='~= 0')
  return {eligible:null,reason:'원본 지급 플래그 형식 미확인'};
 if(!rule.k)return {eligible:true,reason:'원본 지급 제한 없음'};
 if(rule.s==='temp'&&!tempState)
  return {eligible:null,reason:'원본 임시 GetP 범위 미확인'};
 const stateToRead=rule.s==='temp'?tempState:state;
 const v=known(stateToRead[rule.k]);
 const eligible=rule.op==='<'?v<rule.lim:
  rule.op==='=='?v===rule.lim:rule.op==='<='?v<=rule.lim:null;
 return {eligible,reason:eligible===true?'원본 지급 조건 충족':
  eligible===false?'원본 누적 획득 상한 도달':'원본 지급 연산 미복원'};
}
/* Input 'producers' is output from the independently replayed original
 * producer functions. Never decide a drop from a claimed counter alone.
 * producer: {npc, specialIds:[...]} for each boss in actual in-game order.
 */
export function evaluateSpecialAwards(save,producers,{
 mode='current',tempState=null,numericState=null,
 applyUnverifiedWhaleForwardReceipts=false
}={}){
 const state=specialScenario(save,mode).globalVariable;
 const counters={...state};
 const temp=tempState==null?null:{...tempState};
 const events=[];
 for(const producer of producers){
  const npc=Number(producer.npc);
  for(const itemValue of producer.specialIds||[]){
   const id=Number(itemValue),rule=originalConsumerRule(npc,id);
   if(!rule){
    events.push({npc,itemId:id,name:rewardLabel(id),predicted:false,
     status:'원본 지급 함수 미확인',quantity:0});
    continue;
   }
   // A matching producer set the drop flag for THIS clear. A lingering flag
   // in the old save is not evidence of a new drop.
   counters[rule.f]=1;
   const check=consumerGuard(rule,counters,temp,numericState);
   const awarded=check.eligible===true;
   const effects=[],pendingHypotheses=[];
   const unverifiedReceipt=UNVERIFIED_WHALE_FORWARD_RECEIPTS[ruleKey(rule)];
   if(awarded&&unverifiedReceipt&&!applyUnverifiedWhaleForwardReceipts)
    pendingHypotheses.push({
     kind:'원본 지급 후 영수증 카운터 추정',
     key:unverifiedReceipt.key,status:'미검증 · 카운터는 변경하지 않음'
    });
   if(awarded){
    if(rule.k&&rule.s!=='temp'){
     const countBefore=known(counters[rule.k]);
     // The original get_* value counts completed grants, not items in stock.
     const countAfter=SOURCE_CONFIRMED_SET_COUNTERS.includes(ruleKey(rule))?
      1:countBefore+1;
     counters[rule.k]=countAfter;
     // Source's nested GetP(get_fragment)==14/9 is evaluated after the
     // preceding AddBattleDrop(...); AddP(get_fragment,1) statement.
     // This unlocks the completion shop upon reaching 14 or 9 fragments,
     // not on the subsequent 15th or 10th grant.
     const milestone=ORIGINAL_FRAGMENT_MILESTONES.find(row=>
      row.npc===npc&&row.item===id&&row.count===rule.k&&row.after===countAfter);
     if(milestone){
      counters[milestone.shop]=known(counters[milestone.shop])+1;
      effects.push({kind:'잔편 완성 후속 해금',key:milestone.shop,value:counters[milestone.shop]});
     }
    }else if(rule.k&&temp)temp[rule.k]=known(temp[rule.k])+1;
    const name=ruleKey(rule);
    const extra=SOURCE_EXTRA_COUNTER_ACTIONS[name];
    const hypothetical=UNVERIFIED_WHALE_FORWARD_RECEIPTS[name];
    if(hypothetical&&applyUnverifiedWhaleForwardReceipts){
     counters[hypothetical.key]=known(counters[hypothetical.key])+hypothetical.delta;
     effects.push({kind:'가정한 Whale 지급 후 영수증 카운터',
      key:hypothetical.key,value:counters[hypothetical.key],
      sourceVerified:false});
    }
    if(extra){
     if(extra.operator==='AddP')counters[extra.key]=known(counters[extra.key])+extra.delta;
     else if(extra.operator==='SetP')counters[extra.key]=extra.delta;
     else throw Error('복원된 원본 보상 카운터 연산이 유효하지 않습니다.');
    }
    counters[rule.f]=Object.prototype.hasOwnProperty.call(SOURCE_CONFIRMED_POST_AWARD_FLAGS,name)?
     SOURCE_CONFIRMED_POST_AWARD_FLAGS[name]:2;
   }
   // AddBattleDrop's third argument is the item grade, as proven by
   // normal equipment's GetP(drop_*_color) in the SAME parameter position.
   // A fixed grade 5 (orange) is never a grant of five item copies.
   events.push({npc,itemId:id,name:rewardLabel(id),predicted:awarded,
    status:check.reason,quantity:awarded?1:0,
    gradeCode:awarded?rule.q:null,sourceArgument3:rule.q,effects,pendingHypotheses,
    postAwardFlag:awarded?counters[rule.f]:null,
    countKey:rule.k||null,unresolved:check.eligible===null});
  }
 }
 return {mode,events,counters,tempCounters:temp,unresolved:events.filter(e=>e.unresolved).length};
}
/* Do NOT treat the actual save's previous drop_* values as fresh awards.
 * Only the supplied per-clear producer outcomes are consumed. The resulting
 * state continues across all clears with award counters carried forward.
 */
export function forecastSpecialAwards(save,clears,{
 mode='current',tempState=null,numericState=null,numericAfterGrant='unknown',
 tempLifetime='unknown'
}={}){
 if(!['unknown','retained'].includes(numericAfterGrant))
  throw Error('원본 숫자형 GetP 보유 변화 가정이 올바르지 않습니다.');
 if(!['unknown','persist','reset'].includes(tempLifetime))
  throw Error('원본 temp 변수 회차 간 유지 가정이 올바르지 않습니다.');
 if(!Array.isArray(clears))throw Error('관문 결과 배열이 필요합니다.');
 const base=specialScenario(save,mode);
 const state={...base.globalVariable};
 let temp=tempState==null?null:{...tempState};
 const numeric=numericState==null?null:{...numericState};
 const result=[];
 for(const one of clears){
  const out=evaluateSpecialAwards({globalVariable:state},one,{
   mode:'current',tempState:temp,numericState:numeric
  });
  Object.assign(state,out.counters);
  // Preserve the native temp-scoped payout state, not global get_* values.
  temp=out.tempCounters;
  // Original GetP(...,'temp') is scoped, not a global persisted save.
  // With no native proof of its lifetime, never propagate a known value to
  // later gate clears. 'persist' and 'reset' are explicit counterfactuals.
  if(tempLifetime==='unknown')temp=null;
  else if(tempLifetime==='reset'&&temp)temp=Object.fromEntries(
   Object.keys(temp).map(key=>[key,0]));
  if(numeric&&out.events.some(event=>
    event.npc===35221&&event.itemId===3970&&event.predicted)){
   // Source confirmed a newly awarded key, but not how numeric GetP(3970)
   // is mutated by the inventory/quest consumer. Do not invent its value.
   numeric[3970]=numericAfterGrant==='retained'?1:null;
  }
  result.push(out.events);
 }
 return {mode,clears:result,counters:state,tempState:temp,numericState:numeric,
  unresolved:result.flat().filter(e=>e.unresolved).length};
}

const NPC_BY_GATE=Object.freeze({
 '연왕부':{'이총관':33654,'하상':33653,'엽내관':33652,'연왕':33650},
 '창옥':{'무준신':40372,'이장':40373,'장정':40374},
 '벽유교':{'독선생':35219,'미':35214,'불로선인':35221},
 '유씨별원':{'윤무':35260,'고리':35264,'이뢰운':35268}
});
/* Adapter for the four original entry producer replay functions. A caller
 * supplies the producer engine (not a fixed list of known outcomes), allowing
 * the two ownership scenarios to be calculated from the same native game data.
 * The adapter never modifies a deployed engine, a source save or a seed.
 */
export function forecastSpecialsFromProducer(save,gate,producer,clears,{
 mode='current',keyMode=null,tempState=null,numericState=null,
 numericAfterGrant='unknown',tempLifetime='unknown'
}={}){
 if(typeof producer!=='function')throw Error('원본 관문 생성 함수가 필요합니다.');
 const bosses=NPC_BY_GATE[gate];
 if(!bosses)throw Error('출시된 4개 관문만 지원합니다.');
 const scenario=specialScenario(save,mode);
 // Numeric GetP(8915) is an ownership guard, not a get_* claim counter.
 // In an all-unclaimed what-if the key is assumed absent by default, but a
 // caller can choose a specific keep/use scenario explicitly.
 const ownershipMode=keyMode??(mode==='current'?'auto':'absent');
 const replay=producer(scenario,clears,ownershipMode);
 if(!Array.isArray(replay?.output))throw Error('원본 관문 재생 결과가 없습니다.');
 const trace=replay.output.map(clear=>{
  if(!Array.isArray(clear?.results))throw Error('원본 보스별 추첨 정보 누락');
  return clear.results.map(row=>{
   const npc=bosses[row.boss];
   if(!npc)throw Error('원본 보스 정보 누락');
   if(!Array.isArray(row.specialIds))throw Error('원본 특수 추첨 기록 누락');
   return {npc,specialIds:row.specialIds};
  });
 });
 const grants=forecastSpecialAwards(scenario,trace,{
  mode:'current',tempState,numericState,numericAfterGrant,tempLifetime
 });
 const first=new Map();
 for(let i=0;i<grants.clears.length;i++){
  for(const event of grants.clears[i]){
   if(!event.predicted)continue;
   const key=event.npc+':'+event.itemId;
   if(!first.has(key))first.set(key,{
    npc:event.npc,itemId:event.itemId,name:event.name,
    clear:replay.output[i]?.clear??i+1,quantity:event.quantity
   });
  }
 }
 return {gate,mode,output:replay.output,
  grants:grants.clears,firstPredicted:[...first.values()],
  unresolved:grants.unresolved,ownershipMode,
  // Claim-count zeroing alone cannot reconstruct a different quest history:
  // a future gate/key unlock may also depend on independent branch flags.
  questHistoryAssumedUnchanged:mode!=='current',
  // Preserve native-producer uncertainty rather than calling this verified.
  conditional:true};
}

/* Integrated per-clear source replay. This is separate from the legacy
 * precomputed trace replay: the successful consumer's get_* updates and
 * original flag transitions are fed into the next producer invocation.
 * No speculative battle-failure rollback event is injected.
 *
 * A source producer may still leave out native post-battle side effects; the
 * returned result retains a conditional status until native validation.
 */
export function forecastInterleavedSpecials(save,gate,producer,clears,{
 mode='current',keyMode=null,tempState=null,numericState=null,
 numericAfterGrant='unknown',firstItemId=null,
 applyUnverifiedWhaleForwardReceipts=false,tempLifetime='unknown'
}={}){
 if(!['unknown','retained'].includes(numericAfterGrant))
  throw Error('원본 숫자형 GetP 보유 변화 가정이 올바르지 않습니다.');
 if(!['unknown','persist','reset'].includes(tempLifetime))
  throw Error('원본 temp 변수 회차 간 유지 가정이 올바르지 않습니다.');
 if(typeof producer!=='function')throw Error('원본 관문 생성 함수가 필요합니다.');
 if(!Number.isInteger(clears)||clears<1||clears>2000)
  throw Error('1~2000회 범위를 입력하세요.');
 const bosses=NPC_BY_GATE[gate];
 if(!bosses)throw Error('출시된 4개 관문만 지원합니다.');
 if(firstItemId!=null&&!SPECIAL_CONSUMER_RULES.some(r=>
  r.g===gate&&r.i===Number(firstItemId)))
  throw Error('해당 관문에서 추첨하는 원본 특수 보상이 아닙니다.');
 let state=specialScenario(save,mode);
 const ownershipMode=keyMode??(mode==='current'?'auto':'absent');
 let temp=tempState==null?null:{...tempState};
 const numeric=numericState==null?null:{...numericState};
 const first=new Map(),rows=[];
 let stoppedReason=null,stoppedAt=null;
 for(let i=0;i<clears;i++){
  let producerResult;
  try{producerResult=producer(state,1,ownershipMode);}
  catch(error){
   if(error?.code!=='DUNGEON_WEIGHT_EXHAUSTED')throw error;
   stoppedAt=i+1;
   stoppedReason='원본 재료 추첨 가중치가 소진되어 이후 회차를 재현할 수 없습니다.';
   // The source producer declined to make a draw, so no later result,
   // inventory mutation, or invented RNG is appended.
   break;
  }
  if(!producerResult?.nextState||!Array.isArray(producerResult.output)||
     producerResult.output.length!==1)
   throw Error('원본 생성기에서 다음 회차 상태를 반환하지 않았습니다.');
  const one=producerResult.output[0];
  const outcomes=one.results.map(boss=>{
   const npc=bosses[boss.boss];
   if(!npc||!Array.isArray(boss.specialIds))throw Error('보스별 특수 추첨 기록이 없습니다.');
   return {npc,specialIds:boss.specialIds};
  });
  const evaluated=evaluateSpecialAwards(producerResult.nextState,outcomes,{
   tempState:temp,numericState:numeric,
   applyUnverifiedWhaleForwardReceipts
  });
  state={...producerResult.nextState,globalVariable:evaluated.counters};
  temp=evaluated.tempCounters;
  if(tempLifetime==='unknown')temp=null;
  else if(tempLifetime==='reset'&&temp)temp=Object.fromEntries(
   Object.keys(temp).map(key=>[key,0]));
  if(numeric&&evaluated.events.some(event=>
    event.npc===35221&&event.itemId===3970&&event.predicted))
   numeric[3970]=numericAfterGrant==='retained'?1:null;
  for(const event of evaluated.events){
   if(event.predicted){
    const token=event.npc+':'+event.itemId;
    if(!first.has(token))first.set(token,{
     npc:event.npc,itemId:event.itemId,name:event.name,
     clear:i+1,quantity:event.quantity
    });
   }
  }
  rows.push({clear:i+1,producer:one,grants:evaluated.events,
   unresolved:evaluated.unresolved});
  if(firstItemId!=null&&evaluated.events.some(event=>
   event.itemId===Number(firstItemId)&&event.predicted))break;
 }
 return {gate,mode,ownershipMode,rows,firstPredicted:[...first.values()],
  searchedClears:rows.length,requestedClears:clears,
  incomplete:stoppedAt!=null,stoppedAt,stoppedReason,
  firstItemId,foundTarget:firstItemId==null?null:
   rows.some(row=>row.grants.some(event=>event.itemId===Number(firstItemId)&&event.predicted)),
  // Deliberately separate the battle entry and conditional consumer from
  // actual final inventory transaction and quest-state transitions.
  conditional:true,questHistoryAssumedUnchanged:mode!=='current',
  nextState:state,tempState:temp,numericState:numeric,
  unresolved:rows.reduce((sum,row)=>sum+row.unresolved,0)};
}
